-- paperclip:migration-safety-ignore large-create-index-not-concurrently: Drizzle migrations run transactionally, so CONCURRENTLY is unavailable. This (company_id, id) index backs backlog F's gap-free reconnect backfill (heartbeat "heartbeat" stream: WHERE company_id=? AND id>cursor ORDER BY id), turning a full/PK scan filtered by company into an index range scan. The feature is flag-gated and off by default; the one-time build lock is the lesser cost.
CREATE INDEX IF NOT EXISTS "heartbeat_run_events_company_id_id_idx" ON "heartbeat_run_events" USING btree ("company_id","id");
